namespace DotGram.Finance.Fix;

/// <summary>
/// The ninety-three messages FIX 4.4 describes, each a case of <see cref="FixMessage"/>.
/// </summary>
/// <remarks>
/// Nested, because this is a closed set and not ninety-three free names: the set is fixed, every
/// case is a <see cref="FixMessage"/>, and a switch over them is meant to be exhaustive. The
/// package already writes the field hierarchy this way one layer down — <c>FixField.Custom</c>,
/// <c>FixField.SettlDate</c> — and two spellings of one idea in one package is what this removes.
/// At the point of use it reads as what it is: <c>FixMessage.NewOrderSingle</c> says what the
/// thing IS where it is written, and puts the base type in front of every arm of every switch,
/// which is what makes the hierarchy visibly closed where it is taken apart.
/// </remarks>
public abstract partial class FixMessage
{
	internal FixMessage(string messageType, List<FixField> fields)
	{
		MessageType = messageType;
		Fields      = fields;
	}

	/// <summary>
	/// Takes a field of the standard header or trailer, and answers whether the tag was one of
	/// theirs, so that a message type's own constructor can report what neither it nor this took.
	/// </summary>
	/// <param name="field">The field to take.</param>
	protected bool SetStandardField(FixField field)
	{
		switch (field.Tag)
		{
			case   8: BeginString            = (FixField.BeginString)           field; break;
			case   9: BodyLength             = (FixField.BodyLength)            field; break;
			case  10: CheckSum               = (FixField.CheckSum)              field; break;
			case  34: MsgSeqNum              = (FixField.MsgSeqNum)             field; break;
			case  35: MsgType                = (FixField.MsgType)               field; break;
			case  43: PossDupFlag            = (FixField.PossDupFlag)           field; break;
			case  49: SenderCompID           = (FixField.SenderCompID)          field; break;
			case  50: SenderSubID            = (FixField.SenderSubID)           field; break;
			case  52: SendingTime            = (FixField.SendingTime)           field; break;
			case  56: TargetCompID           = (FixField.TargetCompID)          field; break;
			case  57: TargetSubID            = (FixField.TargetSubID)           field; break;
			case  89: Signature              = (FixField.Signature)             field; break;
			case  90: SecureDataLen          = (FixField.SecureDataLen)         field; break;
			case  91: SecureData             = (FixField.SecureData)            field; break;
			case  93: SignatureLength        = (FixField.SignatureLength)       field; break;
			case  97: PossResend             = (FixField.PossResend)            field; break;
			case 115: OnBehalfOfCompID       = (FixField.OnBehalfOfCompID)      field; break;
			case 116: OnBehalfOfSubID        = (FixField.OnBehalfOfSubID)       field; break;
			case 122: OrigSendingTime        = (FixField.OrigSendingTime)       field; break;
			case 128: DeliverToCompID        = (FixField.DeliverToCompID)       field; break;
			case 129: DeliverToSubID         = (FixField.DeliverToSubID)        field; break;
			case 142: SenderLocationID       = (FixField.SenderLocationID)      field; break;
			case 143: TargetLocationID       = (FixField.TargetLocationID)      field; break;
			case 144: OnBehalfOfLocationID   = (FixField.OnBehalfOfLocationID)  field; break;
			case 145: DeliverToLocationID    = (FixField.DeliverToLocationID)   field; break;
			case 212: XmlDataLen             = (FixField.XmlDataLen)            field; break;
			case 213: XmlData                = (FixField.XmlData)               field; break;
			case 347: MessageEncoding        = (FixField.MessageEncoding)       field; break;
			case 369: LastMsgSeqNumProcessed = (FixField.LastMsgSeqNumProcessed)field; break;
			default: return false;
		}

		return true;
	}

	/// <summary>
	/// The MsgType, tag 35.
	/// </summary>
	public string         MessageType { get; }
	/// <summary>
	/// All fields in wire order, including header and trailer; group entries are flattened into the list.
	/// </summary>
	public List<FixField> Fields      { get; }


	/// <summary>
	/// The list of findings that made this message invalid, or null when the message is valid.
	/// </summary>
	public List<string>?                    InvalidFindings        { get; private set; }

	/// <summary>
	/// Adds a finding to the list of invalid findings for this message.
	/// </summary>
	/// <param name="finding">The finding to add.</param>
	protected void AddFinding(string finding)
	{
		if (InvalidFindings == null)
			InvalidFindings = new List<string>();
		InvalidFindings.Add(finding);
	}

